J.cutAt = (plan, t) => {
  const cs = plan.cuts; let lo = 0, hi = cs.length - 1, ans = -1;
  while (lo <= hi) {
    const m = (lo + hi) >> 1;
    const s = cs[m].renderStart ?? cs[m].start;
    if (s <= t) { ans = m; lo = m + 1; } else hi = m - 1;
  }
  for (let i = ans; i >= 0; i--) {
    const s = cs[i].renderStart ?? cs[i].start;
    if (t >= s && t < (cs[i].displayEnd ?? cs[i].end)) return cs[i];
  }
  return null;
};

J.lyricCutsAt = (plan, t) => {
  const inserted=plan.cuts.find(c=>c.insertedAtPlayhead && t>=c.start && t<c.end);
  if(inserted)return [inserted];
  return plan.cuts.filter(c => !c.blank && (c.renderStart ?? c.start) <= t && t < (c.displayEnd ?? c.end)).sort((a, b) => a.index - b.index);
};

J.lyricRenderCut = cut => cut.displayEnd != null ? Object.assign({}, cut, {
  end: cut.displayEnd, dur: cut.displayEnd - cut.start,
  exit: cut.groupExit ?? cut.exit, outDur: cut.groupOutDur ?? cut.outDur,
}) : cut;

